module tt_um_2amlogic_protocol_emulator(ui_in, uo_out, uio_in, uio_out, uio_oe, ena, clk, rst_n);
  input [7:0] ui_in;
  wire [7:0] ui_in;
  output [7:0] uo_out;
  wire [7:0] uo_out;
  input [7:0] uio_in;
  wire [7:0] uio_in;
  output [7:0] uio_out;
  wire [7:0] uio_out;
  output [7:0] uio_oe;
  wire [7:0] uio_oe;
  input ena;
  wire ena;
  input clk;
  wire clk;
  input rst_n;
  wire rst_n;
  wire _unused;
  wire [7:0] fetch_addr;
  wire [15:0] instr_word;
  wire run_phase;
  protocol_core u_core (
    .clk(clk),
    .fetch_addr(fetch_addr),
    .instr_word(instr_word),
    .port_ui_in(ui_in),
    .port_uio_in(uio_in),
    .port_uio_out(uio_out),
    .port_uo_out(uo_out),
    .rst_n(rst_n),
    .run_phase(run_phase)
  );
  protocol_program_memory u_prog_mem (
    .clk(clk),
    .fetch_addr(fetch_addr),
    .instr_word(instr_word),
    .mode_pin(ui_in[7]),
    .rst_n(rst_n),
    .run_phase(run_phase),
    .serial_in(ui_in[0])
  );
  assign _unused = 1'h0;
  assign uio_oe = 8'h00;
endmodule
